<?php include '../auth/cek_login.php';if($_SESSION['role']!='admin')die('Akses ditolak');include '../koneksi.php';$id=(int)$_GET['id'];$x=mysqli_fetch_assoc(mysqli_query($conn,"SELECT * FROM users WHERE id=$id"));if(isset($_POST['update'])){$nama=$_POST['nama'];$role=$_POST['role'];if($_POST['password']){$p=md5($_POST['password']);mysqli_query($conn,"UPDATE users SET nama='".mysqli_real_escape_string($conn,$nama)."',role='$role',password='$p' WHERE id=$id");}else mysqli_query($conn,"UPDATE users SET nama='".mysqli_real_escape_string($conn,$nama)."',role='$role' WHERE id=$id");header('Location:index.php');exit;}?><!doctype html><html><head><link rel="stylesheet" href="../assets/style.css"></head><body><main><h1>Edit User</h1><form method="post"><input value="<?=$x['username']?>" disabled><input name="nama" value="<?=$x['nama']?>" required><input type="password" name="password" placeholder="Password baru"><select name="role"><option <?=$x['role']=='admin'?'selected':''?>>admin</option><option <?=$x['role']=='petugas'?'selected':''?>>petugas</option></select><button name="update">Update</button></form></main></body></html>
